// Masar PWA service worker. Served at ROOT (/masar-sw.min.js) so scope covers
// /masar; *.min.js under www/ ships as static source (no Jinja). Shell + worker
// data API are NETWORK-FIRST (latest build/data win online, cache only when
// unreachable, bounded timeout); fonts are cache-first; stale caches drop on
// activate. BUILD is the bundle content-hash stamped by the vite plugin each build,
// so a deploy changes these bytes -> updatefound -> reload banner. The worker does
// NOT auto-skipWaiting; it activates only when the banner posts SKIP_WAITING.
const BUILD = "4150119c8769";

const CACHE_VERSION = "masar-pwa-v3-" + BUILD;
const SHELL_CACHE = CACHE_VERSION + "-shell";
const DATA_CACHE = CACHE_VERSION + "-data";

// How long to wait for the network before falling back to the cached shell on a
// slow (but not dead) connection.
const SHELL_NETWORK_TIMEOUT_MS = 3000;

const ASSET_BASE = "/assets/apex/worker_portal";

// The app shell: the masar HTML document plus the built SPA bundle and the
// self-hosted fonts. The HTML is cached under /masar (no query string)
// so an offline reload of /masar?w=<token> still matches the shell.
const SHELL_URLS = [
  "/masar",
  ASSET_BASE + "/assets/index.js",
  ASSET_BASE + "/assets/index.css",
  ASSET_BASE + "/fonts/cairo-arabic.woff2",
  ASSET_BASE + "/fonts/cairo-latin.woff2",
  ASSET_BASE + "/fonts/cairo-latin-ext.woff2",
  ASSET_BASE + "/fonts/montserrat-latin.woff2",
  ASSET_BASE + "/fonts/montserrat-latin-ext.woff2",
];

// Identifies a worker data read that is safe to runtime-cache for offline use.
function isWorkerDataRequest(url) {
  return (
    url.pathname === "/api/method/apex.salis.api.masar.get_worker_context" ||
    url.pathname === "/api/method/apex.salis.api.masar.get_worker_home" ||
    url.pathname === "/api/method/apex.salis.api.masar.get_worker_accommodation" ||
    url.pathname === "/api/method/apex.salis.api.masar.get_worker_transport" ||
    url.pathname === "/api/method/apex.salis.api.masar.get_worker_custody" ||
    url.pathname === "/api/method/apex.salis.api.masar.get_worker_request_detail"
  );
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // Cache each shell URL independently: one missing/redirected asset must
      // not abort the whole precache (addAll is all-or-nothing). cache:"reload"
      // bypasses the browser HTTP cache so the precache stores the fresh build.
      await Promise.all(
        SHELL_URLS.map(async (url) => {
          try {
            const res = await fetch(url, { cache: "reload" });
            if (res && (res.ok || res.type === "opaque")) {
              await cache.put(url, res.clone());
            }
          } catch (e) {
            // Best-effort precache; runtime fetch handler will retry online.
          }
        }),
      );
      // Intentionally NOT skipWaiting() here: the new worker waits in "installed"
      // so the SPA can show a reload banner; it activates only on SKIP_WAITING.
    })(),
  );
});

// The reload banner posts SKIP_WAITING to activate the waiting worker on demand,
// so the worker decides when the new build takes over (vs an abrupt auto-reload).
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((k) => k !== SHELL_CACHE && k !== DATA_CACHE)
          .map((k) => caches.delete(k)),
      );
      await self.clients.claim();
    })(),
  );
});

// The worker data API is issued by frappe-ui as a POST (the token travels in
// the JSON body), and the Cache API cannot store a POST. So we cache under a
// SYNTHESIZED GET key built from the endpoint path + the request body, which is
// stable per worker (the body is just {"token": "..."}). This lets a POST read
// be served from cache offline while staying network-first online.
async function dataCacheKey(url, bodyText) {
  return new Request(
    "https://masar-data" + url.pathname + "#" + encodeURIComponent(bodyText || ""),
    { method: "GET" },
  );
}

// Network-first for the worker data API (GET or POST): always try the network
// first so online data is fresh; only fall back to the last cached response
// when the network is unreachable.
async function networkFirstData(request) {
  const cache = await caches.open(DATA_CACHE);
  const url = new URL(request.url);
  // Read the body once (POST); GET has none. Clone so the network fetch still
  // has a consumable body.
  let bodyText = "";
  if (request.method === "POST") {
    try {
      bodyText = await request.clone().text();
    } catch (e) {}
  }
  const key = await dataCacheKey(url, bodyText);
  try {
    const fresh = await fetch(request);
    if (fresh && fresh.ok) {
      // Store a GET-keyed copy of the JSON response for offline use.
      cache.put(key, fresh.clone());
    }
    return fresh;
  } catch (e) {
    const cached = await cache.match(key);
    if (cached) return cached;
    throw e;
  }
}

// Fetch the freshest copy, bypassing the browser HTTP cache, bounded by a
// timeout so a slow link falls back to cache instead of hanging. cache:"reload"
// guarantees a rebuilt same-filename asset (index.js) is actually refetched.
function fetchFresh(request) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), SHELL_NETWORK_TIMEOUT_MS);
  return fetch(request, { cache: "reload", signal: controller.signal }).finally(() =>
    clearTimeout(timer),
  );
}

// Network-first for the app shell (navigation + built bundle): an online worker
// always boots the latest build; the cached shell is the fallback when the
// network is unreachable or too slow (offline-capable). Keeps the cache warm by
// storing every successful response under a stable key.
async function networkFirstShell(request, shellKey) {
  const cache = await caches.open(SHELL_CACHE);
  try {
    const res = await fetchFresh(request);
    if (res && res.ok) cache.put(shellKey || request, res.clone());
    return res;
  } catch (e) {
    const cached = await cache.match(shellKey || request);
    if (cached) return cached;
    throw e;
  }
}

// Cache-first for immutable assets (self-hosted fonts): serve instantly from
// cache, fetch+store on a miss. Fonts never change, so no revalidation needed.
async function cacheFirst(request) {
  const cache = await caches.open(SHELL_CACHE);
  const cached = await cache.match(request);
  if (cached) return cached;
  const res = await fetch(request);
  if (res && res.ok) cache.put(request, res.clone());
  return res;
}

self.addEventListener("fetch", (event) => {
  const request = event.request;

  let url;
  try {
    url = new URL(request.url);
  } catch (e) {
    return;
  }

  // Only handle our own origin.
  if (url.origin !== self.location.origin) return;

  // Worker data API: network-first, fall back to cache offline. frappe-ui
  // issues these as POST (token in the body), so we handle GET and POST here
  // and key the cache on the body — see networkFirstData.
  if (isWorkerDataRequest(url) && (request.method === "GET" || request.method === "POST")) {
    event.respondWith(networkFirstData(request));
    return;
  }

  // Everything below is GET-only (navigations + static subresources).
  if (request.method !== "GET") return;

  // Navigation to /masar (any query string, e.g. ?w=<token>): network-first so
  // an online worker boots the latest build; cached shell only when offline.
  if (request.mode === "navigate" && url.pathname === "/masar") {
    event.respondWith(networkFirstShell(request, "/masar"));
    return;
  }

  // Self-hosted fonts: immutable -> cache-first for speed.
  if (url.pathname.startsWith(ASSET_BASE + "/fonts/")) {
    event.respondWith(cacheFirst(request));
    return;
  }

  // Built bundle (index.js/index.css): network-first so a rebuild is picked up
  // immediately online; cached copy only when offline.
  if (url.pathname.startsWith(ASSET_BASE + "/assets/")) {
    event.respondWith(networkFirstShell(request));
    return;
  }
});
